   100	/**
   101	 * Try to extract venue_name from raw_payload as fallback
   102	 * Conservative: only use alternatives if they clearly look like real venues
   103	 */
   104	function extractVenueFromRawPayload(raw: RawEventInput): string | null {
   105	  const payload = raw.raw_payload;
   106	  if (!payload) return null;
   107	
   108	  const embedded = (payload as any)._embedded;
   109	  const venue = embedded?.venues?.[0];
   110	
   111	  // Primary: first venue name (only if valid)
   112	  const venueName = venue?.name?.trim();
   113	  if (isValidVenueName(venueName)) {
   114	    return venueName;
   115	  }
   116	
   117	  // Secondary fallback: use address line1 when venue name is "undefined"
   118	  // This is imperfect but better than null - allows matching by address later
   119	  const addressLine = venue?.address?.line1?.trim();
   120	  if (addressLine && addressLine.length > 3 && addressLine !== 'undefined') {
   121	    return addressLine;
   122	  }
   123	
   124	  // NO promoter fallback - promoters are companies, not venues
   125	  // NO attractions fallback - attractions are artists, not venues
   126	
   127	  // NO city fallback - "Stockholm" is not a venue
   128	  return null;
   129	}
