   134	function extractVenueAddressFromPayload(raw: RawEventInput): string | null {
   135	  const payload = raw.raw_payload;
   136	  if (!payload) return null;
   137	  
   138	  const venue = (payload as any)?._embedded?.venues?.[0];
   139	  if (!venue) return null;
   140	  
   141	  // Try line1 first
   142	  const line1 = venue?.address?.line1?.trim();
   143	  if (line1 && line1.length > 3 && line1 !== 'undefined') {
   144	    return line1;
   145	  }
   146	  
   147	  // Try line2 as fallback
   148	  const line2 = venue?.address?.line2?.trim();
   149	  if (line2 && line2.length > 3 && line2 !== 'undefined') {
   150	    return line2;
   151	  }
