   156	/**
   157	 * Check if venue name looks like an address (street name + number)
   158	 * This indicates it came from address fallback, not real venue name
   159	 */
   160	function looksLikeAddress(name: string | null): boolean {
   161	  if (!name) return false;
   162	  
   163	  // Common Stockholm street patterns
   164	  const addressPatterns = [
   165	    /^[A-ZÅÄÖ][a-zåäö]+(gatan|vägen|stranden|storget|plan|backen|torget|kvarteret|bryggan|kai)/i, // Swedish streets
   166	    /\d+\s*$/,  // Ends with number (street number)
   167	    /^\d+.*\d+$/, // Contains multiple numbers (address pattern)
   168	  ];
   169	  
   170	  return addressPatterns.some(p => p.test(name));
   171	}
