   173	/**
   174	 * Try to match venue by address against existing venues in database
   175	 * This helps when venue name is corrupted but address is valid
   176	 */
   177	async function findVenueByAddress(address: string): Promise<{ id: string; name: string } | null> {
   178	  if (!address) return null;
   179	  
   180	  // Try exact-ish match (case insensitive)
   181	  const { data: match } = await supabase
   182	    .from('venues')
   183	    .select('id, name, address')
   184	    .ilike('address', address)
   185	    .limit(1)
   186	    .single();
   187	  
   188	  if (match) {
   189	    return { id: match.id, name: match.name };
   190	  }
   191	  
   192	  // Try partial match - address contains venue address
   193	  const { data: partialMatches } = await supabase
   194	    .from('venues')
   195	    .select('id, name, address')
   196	    .ilike('address', `%${address}%`)
   197	    .limit(1)
   198	    .single();
   199	  
   200	  if (partialMatches) {
   201	    return { id: partialMatches.id, name: partialMatches.name };
   202	  }
   203	  
   204	  return null;
   205	}
