   207	/** Resolve venue_id from name + address, creating a new venue record if needed */
   208	async function resolveVenue(raw: RawEventInput): Promise<string | null> {
   209	  let venueName = raw.venue_name?.trim() || null;
   210	
   211	  // Fallback: try to extract from raw_payload
   212	  if (!venueName) {
   213	    const fallbackName = extractVenueFromRawPayload(raw);
   214	    if (fallbackName) {
   215	      console.log(`[normalizer] Using fallback venue_name from raw_payload: "${fallbackName}"`);
   216	      venueName = fallbackName;
   217	    }
   218	  }
   219	
   220	  if (!venueName) {
   221	    console.log(`[normalizer] No venue_name for event ${raw.source}:${raw.source_id ?? 'unknown'} "${raw.title}", skipping venue resolution`);
   222	    return null;
   223	  }
   224	
   225	  // Normalize venue name: trim whitespace and collapse multiple spaces
   226	  const normalizedName = venueName.replace(/\s+/g, ' ');
   227	
   228	  // Try case-insensitive match by name first
   229	  const { data: existing } = await supabase
   230	    .from('venues')
   231	    .select('id')
   232	    .ilike('name', normalizedName)
   233	    .limit(1)
   234	    .single();
   235	
   236	  if (existing) {
   237	    console.log(`[normalizer] Venue matched by name: "${normalizedName}" -> ${existing.id}`);
   238	    return existing.id;
   239	  }
   240	
   241	  // If name looks like an address, try address-based matching
   242	  if (looksLikeAddress(normalizedName)) {
   243	    const address = extractVenueAddressFromPayload(raw) || normalizedName;
   244	    const addressMatch = await findVenueByAddress(address);
   245	    
   246	    if (addressMatch) {
   247	      console.log(`[normalizer] Venue matched by address: "${normalizedName}" -> "${addressMatch.name}" (${addressMatch.id})`);
   248	      return addressMatch.id;
   249	    }
   250	    
   251	    // Try raw_payload address even if venueName didn't come from there
   252	    const rawPayloadAddress = extractVenueAddressFromPayload(raw);
   253	    if (rawPayloadAddress && rawPayloadAddress !== normalizedName) {
   254	      const rawAddressMatch = await findVenueByAddress(rawPayloadAddress);
   255	      if (rawAddressMatch) {
   256	        console.log(`[normalizer] Venue matched by raw_payload address: "${normalizedName}" -> "${rawAddressMatch.name}" (${rawAddressMatch.id})`);
   257	        return rawAddressMatch.id;
   258	      }
   259	    }
   260	  }
   261	
   262	  // Try to create new venue, but handle potential race condition
   263	  console.log(`[normalizer] Creating new venue: "${normalizedName}"`);
   264	  const { data: created, error: insertError } = await supabase
   265	    .from('venues')
   266	    .insert({
   267	      name: normalizedName,
   268	      address: raw.venue_address?.trim() ?? '',
   269	      lat: raw.lat ?? 59.3293, // Default: Stockholm city center
   270	      lng: raw.lng ?? 18.0686,
   271	      location: raw.lat && raw.lng
   272	        ? `POINT(${raw.lng} ${raw.lat})`
   273	        : 'POINT(18.0686 59.3293)',
   274	    })
   275	    .select('id')
   276	    .single();
   277	
   278	  // Handle race condition: another worker might have created the same venue
   279	  if (insertError) {
   280	    if (insertError.code === '23505') { // PostgreSQL unique_violation
   281	      console.log(`[normalizer] Venue already exists (race condition handled): "${normalizedName}"`);
   282	      // Re-fetch the venue
   283	      const { data: raceVenue } = await supabase
   284	        .from('venues')
   285	        .select('id')
   286	        .ilike('name', normalizedName)
   287	        .limit(1)
   288	        .single();
   289	      return raceVenue?.id ?? null;
   290	    }
   291	    console.error(`[normalizer] Failed to create venue: ${insertError.message}`);
   292	    return null;
   293	  }
   294	
   295	  return created?.id ?? null;
   296	}
