   308	export async function processRawEvent(job: Job<RawEventInput>): Promise<void> {
   309	  const raw = job.data;
   310	  const dedupHash = raw.source_id
   311	    ? buildDedupHash(raw.source, raw.source_id)
   312	    : buildDedupHash(raw.source, `${raw.title}::${raw.start_time}`);
   313	
   314	  console.log(`[normalizer] Processing ${raw.source}:${raw.source_id ?? 'unknown'} "${raw.title}"`);
   315	
   316	  // Check for existing event (primary dedup)
   317	  const { data: existing } = await supabase
   318	    .from('events')
   319	    .select('id, updated_at')
   320	    .eq('dedup_hash', dedupHash)
   321	    .single();
   322	
   323	  if (existing) {
   324	    console.log(`[normalizer] Updating existing event: ${existing.id}`);
   325	  }
   326	
   327	  const venue_id = await resolveVenue(raw);
   328	  const category_ids = await resolveCategoryIds(raw.categories);
   329	
   330	  // Get primary category slug (first category from the normalized list)
   331	  const category_slug = raw.categories?.[0] ?? 'community';
   332	  
   333	  console.log(`[normalizer] venue_id=${venue_id ?? 'null'}, category_slug=${category_slug}`);
   334	
   335	  const normalized: Partial<NormalizedEvent> & Record<string, unknown> = {
   336	    title_en: raw.title,
   337	    title_sv: raw.detected_language === 'sv' ? raw.title : null,
   338	    description_en: raw.description ?? null,
   339	    description_sv: raw.detected_language === 'sv' ? raw.description : null,
   340	    start_time: raw.start_time,
   341	    end_time: raw.end_time,
   342	    source: raw.source,
   343	    source_id: raw.source_id,
   344	    venue_id,
   345	    lat: raw.lat ?? 59.3293,
   346	    lng: raw.lng ?? 18.0686,
   347	    location: `POINT(${raw.lng ?? 18.0686} ${raw.lat ?? 59.3293})`,
   348	    is_free: raw.is_free,
   349	    price_min_sek: raw.price_min_sek,
   350	    price_max_sek: raw.price_max_sek,
   351	    ticket_url: raw.ticket_url,
   352	    image_url: raw.image_url,
   353	    dedup_hash: dedupHash,
   354	    category_slug,  // Denormalized for direct filtering
   355	    status: 'published',
   356	    raw_data: raw.raw_payload,
   357	  };
   358	
   359	  let event_id: string;
   360	
   361	  if (existing) {
   362	    // Update existing event
   363	    const { data: updated, error: updateError } = await supabase
   364	      .from('events')
   365	      .update({ ...normalized, updated_at: new Date().toISOString() })
   366	      .eq('id', existing.id)
   367	      .select('id')
   368	      .single();
   369	
   370	    if (updateError || !updated) {
   371	      console.error(`[normalizer] Failed to update event ${existing.id}:`, updateError?.message);
   372	      throw new Error(`Update failed for event ${existing.id}`);
   373	    }
   374	    event_id = updated.id;
   375	    console.log(`[normalizer] ✅ Updated: event_id=${event_id}`);
   376	    
   377	    // Log update
   378	    await logIngestion(raw.source, 'updated');
   379	  } else {
   380	    // Insert new event
   381	    console.log(`[normalizer] Inserting new event (hash: ${dedupHash})...`);
   382	    const { data: inserted, error: insertError } = await supabase
   383	      .from('events')
   384	      .insert(normalized)
   385	      .select('id')
   386	      .single();
   387	
   388	    if (insertError || !inserted) {
   389	      console.error(`[normalizer] Failed to insert event:`, insertError?.message);
   390	      throw new Error(`Insert failed for event (hash: ${dedupHash})`);
   391	    }
   392	    event_id = inserted.id;
   393	    console.log(`[normalizer] ✅ Inserted: event_id=${event_id}`);
   394	
   395	    // Insert category links
   396	    if (category_ids.length > 0) {
   397	      await supabase.from('event_categories').insert(
   398	        category_ids.map((cat_id) => ({ event_id, category_id: cat_id }))
   399	      );
   400	    }
   401	    
   402	    // Log insert
   403	    await logIngestion(raw.source, 'inserted');
   404	  }
   405	
   406	  // Enqueue Meilisearch sync
   407	  await searchSyncQueue.add('sync', { event_id, action: 'upsert' });
   408	}
