   411	async function logIngestion(source: string, action: 'inserted' | 'updated'): Promise<void> {
   412	  try {
   413	    await supabase.from('ingestion_logs').insert({
   414	      source,
   415	      action,
   416	      timestamp: new Date().toISOString(),
